class Solution {
public:
    int minimumLengthEncoding(vector<string>& words) {
        set<string> st;
        for(auto it:words)
            st.insert(it);
        for(auto it:words)
        {
            for(int i=1;i<it.size();i++)
                st.erase(it.substr(i));
        }
        int ans=0;
        for(auto it:st)
            ans+=it.size()+1;
        return ans;
    }
};
