struct Node {
    Node* links[26];
    bool isempty=true;
};
class Solution {
public:
    int minimumLengthEncoding(vector<string>& words) {
        Node* root=new Node();
        int ans=1;
        for(auto it:words)
        {
            Node* curr=root;
            bool newword=false;
            for(int i=it.size()-1;i>=0;i--)
            {
                int val=it[i]-'a';
                if(curr->isempty and !newword)
                    ans-=it.size()-i;
                if(!curr->links[val])
                {
                    curr->links[val]=new Node();
                    newword=true;
                    curr->isempty=false;
                }
                curr=curr->links[val];
            }
            if(newword)
                ans+=it.size()+1;
        }
        return ans;
    }
};
